/* use this for style redefinitions to awoid problems with
unpredictable css rules order in build */
.pc-content-layout-block {
  position: relative;
}
.pc-content-layout-block__content, .pc-content-layout-block__files {
  z-index: 10;
  position: relative;
}
.pc-content-layout-block__files {
  margin-top: 24px;
}
.pc-content-layout-block__files_size_s {
  font-size: var(--g-text-body-2-font-size);
  line-height: var(--g-text-body-2-line-height);
}
.pc-content-layout-block__files_size_l, .pc-content-layout-block__files_size_xl {
  font-size: var(--g-text-body-3-font-size);
  line-height: var(--g-text-body-3-line-height);
}
.pc-content-layout-block__files_centered {
  margin-left: auto;
  margin-right: auto;
}
.pc-content-layout-block__files a {
  text-decoration: none;
}
.pc-content-layout-block__file {
  margin-bottom: 12px;
}
.pc-content-layout-block__file:last-child {
  margin-bottom: 0;
}
.pc-content-layout-block__background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
.pc-content-layout-block__background-item {
  height: 100%;
  border-radius: var(--pc-border-radius);
}
.pc-content-layout-block_background {
  padding: 64px;
}
.pc-content-layout-block_theme_dark {
  --g-color-line-focus: var(--pc-color-line-focus-dark);
}
@media (max-width: 577px) {
  .pc-content-layout-block_background {
    padding: 32px;
  }
